mapper.select:
select * from ( SELECT a.id, a.rep_no repNo, a.user_id userId, a.user_name userName, a.user_gender userGender, ( YEAR (a.create_date) - YEAR (a.birth_date) - 1 ) + ( DATE_FORMAT(a.birth_date, '%m%d') <= DATE_FORMAT(a.create_date, '%m%d') ) AS age, DATE_FORMAT(a.start_date, '%Y-%m-%d') startDate, DATE_FORMAT(a.end_date, '%Y-%m-%d') endEate, b.user_tel userTel, ifnull(a.rep_status,0) repStatus, ifnull(a.pdf_path, '') pdfPath, a.src, a.company_id companyId, a.level, a.content, DATE_FORMAT( rep_status_time, '%Y-%m-%d %H:%i:%s' ) repStatusTime, DATE_FORMAT( pdf_ecg_end_time, '%Y-%m-%d %H:%i:%s' ) pdfEcgEndTime, CASE WHEN ifnull(a.rep_status, 0) = 1 THEN rep_status_time ELSE '' END pdfTime, IFNULL( ( SELECT sum( timestampdiff( SECOND, ecg_start_time, ecg_end_time ) ) diff FROM cust_user_ecg_rec WHERE ecg_id IN ( SELECT ecg_id FROM cust_user_ecg_warning_report_detail WHERE rep_id = a.id ) ), 0 ) duration, ( SELECT DATE_FORMAT( max(ecg_end_time), '%Y-%m-%d %H:%i:%s' ) FROM cust_user_ecg_warning_report_detail WHERE rep_id = a.id ) lastEcgEndTime FROM cust_user_ecg_warning_report a INNER JOIN cust_userinfo b ON a.user_id = b.user_id where a.company_id in (select distinct company_id from comm_user_mng_dept a INNER JOIN comm_dept b ON a.dept_id = b.dept_id where user_id=#{loginUserId}) )temp where 1=1
and repStatus = #{tm}
and startDate >= #{tm}
and startDate <= #{tm}
and ${key} like CONCAT('%',#{tm,jdbcType=VARCHAR}, '%')
order by ${column} ${order}
order by id desc
